    pat=re.compile(r'Model:\s*(\S+)\s*\|\s*Dataset:\s*(\S+)\s*\|\s*(Acc|F1):\s*([0-9.]+)\s*\|\s*Rows:\s*(\d+)\s*\|\s*Feats:\s*(\d+)')
    for line in open('/app/results/team_beta/benchmark_log.txt'):
        q=pat.search(line)
        if q and q.group(3)=='Acc': add('beta',q.group(1),q.group(2),q.group(4),q.group(5),q.group(6))
    return R

def model_norm(m):
    s=re.sub(r'[^a-z0-9]','',m.lower())
    s=re.sub(r'v\d+$','',s)
    return {'catboost':'CatBoost','ftt':'FT-Transformer','fttransformer':'FT-Transformer','lightgbm':'LightGBM','lgbm':'LightGBM','mlp':'MLP','multilayerperceptron':'MLP','randomforest':'RandomForest','rf':'RandomForest','resnet':'ResNet','saint':'SAINT','xgboost':'XGBoost','xgb':'XGBoost'}.get(s,m)

