    q={'bankmkt':'bankmarketing','bankmarketing':'bankmarketing','creditg':'creditg','miniboone':'miniboone','adult':'adult','electricity':'electricity','elec':'electricity','gesture':'gesture','jungle':'jungle','jannis':'jannis','albert':'albert','helena':'helena','phoneme':'phoneme','volkert':'volkert'}
    return q.get(s,s)

def eval_mode(R, mn, dn, pair_first, eps):
    data=[x for x in R if x['r']>=1000 and x['f']<=50 and (eps or x['src']!='epsilon')]
    if mn:
        for x in data: x['m']=model_norm(x['m'])
    if dn:
        for x in data: x['d']=data_norm(x['d'])
    by=defaultdict(lambda: defaultdict(list))
    if pair_first:
        for x in data: by[x['m']][x['d']].append(x['a'])
        vals={m:[sum(v)/len(v) for v in dd.values()] for m,dd in by.items()}
    else:
        for x in data: by[x['m']][x['d']].append(x['a'])
        vals={}
        for m,dd in by.items():
            allv=[a for vs in dd.values() for a in vs]
            vals[m]=allv
    stat=[]
    for m,vs in vals.items():
        if len(vs)>=5: stat.append((sum(vs)/len(vs),len(vs),m))
    stat.sort(reverse=True)
    return stat

R=parse_all()
for eps in [True,False]:
    for mn in [False,True]:
        for dn in [False,True]:
            for pf in [False,True]:
                st=eval_mode(R,mn,dn,pf,eps)
                top=st[0] if st else None
                tag=f"eps={eps} model_norm={mn} data_norm={dn} pair_first={pf}"
                print(f"{tag:55s} -> {top}")
